	private static void interruptPublication(Path target, LmdbBulkLoadGeneration.PublicationStage cut)
			throws IOException {
		assertThatThrownBy(() -> builder(target).publicationHook(new LmdbBulkLoadGeneration.PromotionHook() {
			@Override
			public void beforeMove(int index, Path source, Path destination) {
			}

			@Override
			public void onStage(LmdbBulkLoadGeneration.PublicationStage stage) throws IOException {
				if (stage == cut) {
					throw new IOException("test publication cutoff");
				}
			}
		}).build().load(new ByteArrayInputStream(INPUT), "urn:bulk:", RDFFormat.NTRIPLES))
				.isInstanceOf(IOException.class)
				.hasMessageContaining("test publication cutoff");
		for (String name : List.of(LmdbBulkLoadGeneration.MARKER_FILE_NAME,
				LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)) {
			Properties metadata = new Properties();
			try (var input = Files.newInputStream(target.resolve(name))) {
				metadata.load(input);
			}
			assertThat(metadata.getProperty("version")).isEqualTo("3");
		}
	}

	private static void interruptAfter(Path target, BulkLoadPhase cut) {
		AtomicBoolean reached = new AtomicBoolean();
		assertThatThrownBy(() -> builder(target).progressListener(progress -> {
			if (progress.phase() == cut && progress.phaseComplete()) {
				reached.set(true);
			}
		})
				.cancellationSignal(reached::get)
				.build()
				.load(new ByteArrayInputStream(INPUT), "urn:bulk:", RDFFormat.NTRIPLES))
						.isInstanceOf(CancellationException.class);
		assertThat(reached).isTrue();
	}

