	private static LmdbBulkLoader.Builder builder(Path target) {
		return LmdbBulkLoader.builder(target, config())
				.parserMode(LmdbBulkLoader.ParserMode.FAST)
				.partitionCount(4)
				.workers(1)
				.memoryBudgetBytes(16L * 1024 * 1024)
				.maxOpenFiles(16);
	}

	/** Preserves a valid checksum so the fixture tests format admission instead of corruption fallback. */
	private static void rewriteFormat(Path target, String version) throws Exception {
		rewriteFormat(target, version, version == null ? "2" : "3");
	}

	private static void rewriteFormat(Path target, String version, String workspaceVersion) throws Exception {
		for (String name : List.of("state.properties", "state.previous.properties")) {
			Path path = BulkLoadWorkspace.controlDirectory(target).resolve(name);
			if (!Files.exists(path)) {
				continue;
			}
			rewriteFormatFile(path, version, workspaceVersion);
		}
	}

	private static void rewriteFormatFile(Path path, String version, String workspaceVersion) throws Exception {
		Properties properties = new Properties();
		try (var input = Files.newInputStream(path)) {
			properties.load(input);
		}
		properties.setProperty("version", workspaceVersion);
		if (version == null) {
			properties.remove(FORMAT_PROPERTY);
		} else {
			properties.setProperty(FORMAT_PROPERTY, version);
		}
		MessageDigest checksum = MessageDigest.getInstance("SHA-256");
		properties.stringPropertyNames().stream().filter(key -> !key.equals("checksum")).sorted().forEach(key -> {
			checksum.update(key.getBytes(StandardCharsets.UTF_8));
			checksum.update((byte) '=');
			checksum.update(properties.getProperty(key).getBytes(StandardCharsets.UTF_8));
			checksum.update((byte) '\n');
		});
		properties.setProperty("checksum", HexFormat.of().formatHex(checksum.digest()));
		try (var output = Files.newOutputStream(path)) {
			properties.store(output, "Persisted bulk format fixture");
		}
	}

	private static Properties storeProperties(Path target) throws IOException {
		Properties properties = new Properties();
		try (var input = Files.newInputStream(target.resolve("store.properties"))) {
			properties.load(input);
		}
		return properties;
	}

	private static Map<Path, byte[]> snapshot(Path root) throws IOException {
		Map<Path, byte[]> result = new TreeMap<>();
		try (var files = Files.walk(root)) {
			for (Path file : files.filter(Files::isRegularFile).toList()) {
				result.put(root.relativize(file), Files.readAllBytes(file));
			}
		}
		return result;
	}

	private static void assertSnapshotEquals(Map<Path, byte[]> expected, Map<Path, byte[]> actual) {
		assertThat(actual.keySet()).isEqualTo(expected.keySet());
		expected.forEach((path, bytes) -> assertThat(actual.get(path)).as(path.toString()).isEqualTo(bytes));
	}

	private static void runChild(String classpath, String mainClass, Path target, int expectedExit, Path log)
			throws Exception {
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-cp", classpath, mainClass, target.toString())
						.redirectErrorStream(true)
						.redirectOutput(log.toFile())
						.start();
		try {
			assertThat(process.waitFor(30, TimeUnit.SECONDS)).as("child process completed: %s", mainClass).isTrue();
			assertThat(process.exitValue()).as(Files.readString(log)).isEqualTo(expectedExit);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				process.waitFor(10, TimeUnit.SECONDS);
			}
		}
	}

	/** Leaves the real current publication marker around native format-7 files, without a publication manifest. */
	public static final class FormatSevenPartialWriter {
		public static void main(String[] args) throws Exception {
			try (LmdbBulkLoadGeneration generation = LmdbBulkLoadGeneration.create(Path.of(args[0]))) {
				SailRepository repository = new SailRepository(
						new LmdbStore(generation.directory().toFile(), config()));
				repository.init();
				try (var connection = repository.getConnection()) {
					connection.add(new ByteArrayInputStream(INPUT), "urn:bulk:", RDFFormat.NTRIPLES);
				} finally {
					repository.shutDown();
				}
				Runtime.getRuntime().halt(23);
			}
		}
	}

